package com.example.pryanik.commands;

import com.example.pryanik.PryanikPlugin;
import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.player.AsyncPlayerChatEvent;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.ItemMeta;
import java.io.File;
import java.nio.file.*;
import java.util.*;

public final class WorldCommand implements CommandExecutor,Listener,TabCompleter {
 private static final String TITLE="§8Миры сервера",TYPE_TITLE="§8Выберите тип мира";
 private final PryanikPlugin plugin;private final Set<UUID> awaitingWorldName=Collections.synchronizedSet(new HashSet<>());
 public WorldCommand(PryanikPlugin plugin){this.plugin=plugin;}
 @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){
  if(sender instanceof Player player&&plugin.inCombat(player.getUniqueId())&&!((args.length>0)&&Set.of("where","here","где").contains(args[0].toLowerCase(Locale.ROOT)))){sender.sendMessage("§cНельзя использовать /world в бою.");return true;}if(args.length==0||args[0].equalsIgnoreCase("ui")){if(!(sender instanceof Player p)){sender.sendMessage("Только игрок.");return true;}if(!authorized(p)){p.sendMessage("§cМеню управления мирами доступно только оператору.");return true;}if(!plugin.authed(p.getUniqueId())){p.sendMessage("§cСначала войдите.");return true;}open(p);return true;}
  String sub=args[0].toLowerCase(Locale.ROOT);
   if(sub.equals("where")||sub.equals("here")||sub.equals("где")){if(!(sender instanceof Player p)){sender.sendMessage("Только игрок может посмотреть своё местоположение.");return true;}if(!plugin.authed(p.getUniqueId())){p.sendMessage("§cСначала войдите.");return true;}World w=p.getWorld();String dimension=switch(w.getEnvironment()){case NORMAL->"Обычный мир (Overworld)";case NETHER->"Нижний мир (Nether)";case THE_END->"Край (The End)";default->w.getEnvironment().name();};String instance=plugin.instanceOf(w.getName());p.sendMessage("§6Текущее местоположение:");p.sendMessage("§7Мир: §f"+w.getName());p.sendMessage("§7Измерение: §f"+dimension);p.sendMessage("§7Гриф: §f"+(instance==null?"лобби/обычный мир":instance));return true;}
  if(sub.equals("setbase")){if(sender instanceof Player player&&plugin.gameModes().isModeWorld(player.getWorld())){sender.sendMessage("§cУправление мирами недоступно из игровых грифов.");return true;}if(!authorized(sender)){ sender.sendMessage("§cТолько оператор может менять базовый мир.");return true;}if(args.length!=2||!args[1].matches("[A-Za-z0-9_-]{1,32}")){sender.sendMessage("§e/world setbase <имя>");return true;}File propsFile=new File(Bukkit.getWorldContainer().getAbsoluteFile(),"server.properties");Properties props=new Properties();try(java.io.FileInputStream in=new java.io.FileInputStream(propsFile)){props.load(in);props.setProperty("level-name",args[1]);try(java.io.FileOutputStream out=new java.io.FileOutputStream(propsFile)){props.store(out,"Minecraft server properties");}sender.sendMessage("§aБазовый мир установлен: §e"+args[1]+"§a. Перезапусти Paper, чтобы связка Overworld/Nether/End создалась стандартно.");}catch(Exception ex){sender.sendMessage("§cНе удалось изменить server.properties.");}return true;}
  if(sub.equals("setjoin")){ if(!authorized(sender)){sender.sendMessage("§cТолько оператор может менять мир входа.");return true;}if(args.length!=2){sender.sendMessage("§e/world setjoin <имя_мира>");return true;}World w=Bukkit.getWorld(args[1]);if(w==null){sender.sendMessage("§cМир должен быть загружен. Сначала /world load <имя>.");return true;}plugin.getConfig().set("join-world",w.getName());plugin.saveConfig();sender.sendMessage("§aМир входа установлен: §e"+w.getName());return true;}
  if(sub.equals("delete")){if(!authorized(sender)){sender.sendMessage("§cУдалять миры может только оператор.");return true;}if(args.length!=3||!args[2].equals("DELETE")){sender.sendMessage("§cПодтверди безвозвратное удаление командой: /world delete <имя> DELETE");return true;}return deleteWorld(sender,args[1]);}
  if(sub.equals("list")){list(sender);return true;}
  if(sub.equals("create-set")||sub.equals("create3")){if(!authorized(sender)){sender.sendMessage("§cСоздание доступно оператору.");return true;}if(args.length!=2){sender.sendMessage("§e/world create-set <имя>");return true;}return createSet(sender,args[1]);}if(sub.equals("create")){if(!authorized(sender)){sender.sendMessage("§cСоздание доступно оператору.");return true;}if(args.length<2||args.length>3){sender.sendMessage("§e/world create <имя> [normal|nether|end]");return true;}return create(sender,args[1],args.length==3?args[2]:"normal");}
  if(sub.equals("load")){if(!authorized(sender)){sender.sendMessage("§cЗагрузка доступна оператору.");return true;}if(args.length!=2){sender.sendMessage("§e/world load <имя>");return true;}World w=Bukkit.getWorld(args[1]);if(w==null)w=Bukkit.createWorld(new WorldCreator(args[1]));if(w==null)sender.sendMessage("§cНе удалось загрузить мир.");else{try{plugin.db().rememberWorld(w.getName(),w.getEnvironment().name());}catch(Exception ex){plugin.getLogger().warning("Cannot persist loaded world "+w.getName()+": "+ex);}sender.sendMessage("§aМир загружен и добавлен в реестр: §e"+w.getName());}return true;}
  if(sub.equals("unload")){if(!authorized(sender)){sender.sendMessage("§cВыгрузка доступна оператору.");return true;}if(args.length!=2){sender.sendMessage("§e/world unload <имя>");return true;}World w=Bukkit.getWorld(args[1]);if(w==null){sender.sendMessage("§cМир не загружен.");return true;}if(isProtected(w)||!w.getPlayers().isEmpty()){sender.sendMessage("§cНельзя выгрузить основной мир или мир с игроками.");return true;}sender.sendMessage(Bukkit.unloadWorld(w,true)?"§aМир выгружен с сохранением.":"§cНе удалось выгрузить мир.");return true;}
  if(sub.equals("tp")){if(!(sender instanceof Player p)){sender.sendMessage("Только игрок может телепортироваться.");return true;}if(!plugin.authed(p.getUniqueId())){p.sendMessage("§cСначала войдите.");return true;}if(args.length!=2){p.sendMessage("§e/world tp <имя>");return true;}World w=Bukkit.getWorld(args[1]);if(w==null){p.sendMessage("§cМир не загружен.");return true;}p.teleport(w.getSpawnLocation());p.sendMessage("§aТелепортирован в §e"+w.getName());return true;}
  sender.sendMessage("§e/world [where|ui|list|tp <имя>|setjoin <мир>|setbase <имя>|create <имя> [normal|nether|end]|load <имя>|unload <имя>|delete <имя> DELETE]");return true;
 }
 private boolean authorized(CommandSender s){if(s.isOp())return true;if(!(s instanceof Player p))return false;try{return plugin.db().rank(p.getUniqueId()).canUseWorld();}catch(Exception ex){return false;}}
 private boolean isProtected(World w){return w==Bukkit.getWorlds().get(0)||w.getName().equalsIgnoreCase("world")||w.getName().equalsIgnoreCase("world_nether")||w.getName().equalsIgnoreCase("world_the_end");}
 private boolean createSet(CommandSender sender,String base){ if(!base.matches("[A-Za-z0-9_-]{1,24}")){sender.sendMessage("§cИмя мира должно быть 1-24 символа.");return true;} String[] names={base,base+"_nether",base+"_the_end",base+"_spawn"};for(String n:names){if(Bukkit.getWorld(n)!=null||new File(Bukkit.getWorldContainer(),n).exists()){sender.sendMessage("§cМир или папка уже существует: §e"+n);return true;}} List<World> made=new ArrayList<>(); try{World a=Bukkit.createWorld(new WorldCreator(names[0]).environment(World.Environment.NORMAL));if(a==null)throw new IllegalStateException("Overworld create failed");made.add(a);World b=Bukkit.createWorld(new WorldCreator(names[1]).environment(World.Environment.NORMAL));if(b==null)throw new IllegalStateException("Nether create failed");made.add(b);World c=Bukkit.createWorld(new WorldCreator(names[2]).environment(World.Environment.NORMAL));if(c==null)throw new IllegalStateException("End create failed");made.add(c);Path spawnFolder=new File(Bukkit.getWorldContainer(),names[3]).toPath();com.example.pryanik.SpawnTemplate.install(plugin,names[3],spawnFolder);World spawn=Bukkit.createWorld(new WorldCreator(names[3]).environment(World.Environment.NORMAL));if(spawn==null)throw new IllegalStateException("Spawn dimension create failed");made.add(spawn);plugin.db().rememberWorldSet(base,names[0],names[1],names[2],names[3]);sender.sendMessage("§aСоздана связка миров: §e"+names[0]+", "+names[1]+", "+names[2]+", "+names[3]);sender.sendMessage("§7Телепорт в основу: /world tp "+names[0]);}catch(Exception ex){for(World w:made)Bukkit.unloadWorld(w,true);sender.sendMessage("§cОшибка создания связки. Папки миров не удалены; проверьте БД/логи.");plugin.getLogger().severe("Linked world set creation failed: "+ex);}return true;} private boolean create(CommandSender s,String name,String type){if(!name.matches("[A-Za-z0-9_-]{1,32}")){s.sendMessage("§cНедопустимое имя мира.");return true;}World.Environment env=switch(type.toLowerCase(Locale.ROOT)){case "normal"->World.Environment.NORMAL;case "nether"->World.Environment.NETHER;case "end"->World.Environment.THE_END;default->null;};if(env==null){s.sendMessage("§cТип: normal, nether или end.");return true;}if(Bukkit.getWorld(name)!=null){s.sendMessage("§cМир уже загружен.");return true;}World w=Bukkit.createWorld(new WorldCreator(name).environment(env));if(w==null){s.sendMessage("§cНе удалось создать мир.");return true;}try{plugin.db().rememberWorld(w.getName(),w.getEnvironment().name());}catch(Exception ex){s.sendMessage("§cМир создан, но запись в PostgreSQL не удалась; при перезапуске его не загрузить.");plugin.getLogger().warning("Cannot persist world "+name+": "+ex);}s.sendMessage("§aМир создан и сохранён в реестре БД: §e"+w.getName());return true;}
 private boolean deleteWorld(CommandSender sender,String name){if(!name.matches("[A-Za-z0-9_-]{1,32}")){sender.sendMessage("§cНедопустимое имя мира.");return true;}World w=Bukkit.getWorld(name);if(w==null){sender.sendMessage("§cСначала загрузите мир для проверки: /world load "+name);return true;}if(isProtected(w)){sender.sendMessage("§cУдаление основного мира запрещено.");return true;}if(!w.getPlayers().isEmpty()){sender.sendMessage("§cВ мире ещё есть игроки.");return true;}String join=plugin.getConfig().getString("join-world","");if(name.equalsIgnoreCase(join)){sender.sendMessage("§cСначала смените мир входа: /world setjoin <мир>.");return true;}Path container=Bukkit.getWorldContainer().getAbsoluteFile().toPath().normalize(),folder=w.getWorldFolder().getAbsoluteFile().toPath().normalize();if(!folder.startsWith(container)||folder.equals(container)){sender.sendMessage("§cНебезопасный путь мира.");return true;}if(!Bukkit.unloadWorld(w,true)){sender.sendMessage("§cНе удалось выгрузить мир.");return true;}try{plugin.db().forgetWorld(name);}catch(Exception ex){sender.sendMessage("§cНе удалось удалить запись мира из PostgreSQL; удаление папки отменено.");plugin.getLogger().warning("Cannot forget world "+name+": "+ex);Bukkit.createWorld(new WorldCreator(name).environment(w.getEnvironment()));return true;}try{try(var paths=Files.walk(folder)){for(Path path:paths.sorted(Comparator.reverseOrder()).toList())Files.delete(path);}sender.sendMessage("§cМир "+name+" и папка удалены безвозвратно.");}catch(Exception ex){sender.sendMessage("§cМир выгружен, папка удалена не полностью.");plugin.getLogger().warning("World delete failed: "+ex);}return true;}
 private void list(CommandSender s){s.sendMessage("§6Загруженные миры:");for(World w:Bukkit.getWorlds())s.sendMessage("§7• §f"+w.getName()+" §8["+w.getEnvironment()+"] §7игроков: "+w.getPlayers().size());}
 private ItemStack icon(Material m,String title,String... lore){ItemStack i=new ItemStack(m);ItemMeta meta=i.getItemMeta();meta.setDisplayName(title);meta.setLore(Arrays.asList(lore));i.setItemMeta(meta);return i;}
 private void open(Player p){Inventory inv=Bukkit.createInventory(null,54,TITLE);int slot=0;for(World w:Bukkit.getWorlds()){if(slot>=45)break;Material m=w.getEnvironment()==World.Environment.NETHER?Material.NETHERRACK:w.getEnvironment()==World.Environment.THE_END?Material.END_STONE:Material.GRASS_BLOCK;inv.setItem(slot++,icon(m,"§a"+w.getName(),"§7Тип: "+w.getEnvironment(),"§7Игроков: "+w.getPlayers().size(),"§eНажмите для телепортации"));}if(authorized(p)){inv.setItem(45,icon(Material.EMERALD,"§aСоздать мир","§7Создать с выбором типа"));inv.setItem(47,icon(Material.CHEST,"§bЗагрузить существующий","§7Папка мира на диске"));inv.setItem(49,icon(Material.COMPASS,"§eМир входа","§7Текущий: "+plugin.getConfig().getString("join-world","не задан"),"§7Используй /world setjoin <имя>"));inv.setItem(51,icon(Material.BARRIER,"§cВыгрузить мир","§7Только пустой мир"));}p.openInventory(inv);}
 private void openType(Player p,String name){Inventory inv=Bukkit.createInventory(null,27,TYPE_TITLE);inv.setItem(11,icon(Material.GRASS_BLOCK,"§aОбычный мир","§7Создать "+name+" (normal)"));inv.setItem(13,icon(Material.NETHERRACK,"§cНижний мир","§7Создать "+name+" (nether)"));inv.setItem(15,icon(Material.END_STONE,"§dЭнд","§7Создать "+name+" (end)"));p.openInventory(inv);}
 private void openLoad(Player p){Inventory inv=Bukkit.createInventory(null,54,"§8Загрузить мир");File[] dirs=Bukkit.getWorldContainer().listFiles(File::isDirectory);int slot=0;if(dirs!=null)for(File d:dirs){if(slot>=45)break;if(new File(d,"level.dat").isFile()&&Bukkit.getWorld(d.getName())==null)inv.setItem(slot++,icon(Material.CHEST,"§b"+d.getName(),"§7Загрузить этот мир"));}if(slot==0)inv.setItem(22,icon(Material.BARRIER,"§cНет выгруженных миров"));p.openInventory(inv);}
 private void openUnload(Player p){Inventory inv=Bukkit.createInventory(null,54,"§8Выгрузить мир");int slot=0;for(World w:Bukkit.getWorlds()){if(slot>=45)break;if(!isProtected(w)&&w.getPlayers().isEmpty())inv.setItem(slot++,icon(Material.BARRIER,"§c"+w.getName(),"§7Сохранить и выгрузить"));}if(slot==0)inv.setItem(22,icon(Material.BARRIER,"§cНет доступных миров"));p.openInventory(inv);}
 @EventHandler(priority=EventPriority.HIGHEST) public void chat(AsyncPlayerChatEvent e){Player p=e.getPlayer();if(!awaitingWorldName.remove(p.getUniqueId()))return;e.setCancelled(true);String name=e.getMessage().trim();if(name.equalsIgnoreCase("отмена")||name.equalsIgnoreCase("cancel")){p.sendMessage("§7Создание отменено.");return;}Bukkit.getScheduler().runTask(plugin,()->{if(!authorized(p)||!name.matches("[A-Za-z0-9_-]{1,32}")){p.sendMessage("§cНедопустимое имя или недостаточно прав.");return;}p.getPersistentDataContainer().set(new NamespacedKey(plugin,"world_create_name"),org.bukkit.persistence.PersistentDataType.STRING,name);openType(p,name);});}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;String title=e.getView().getTitle();if(!Set.of(TITLE,TYPE_TITLE,"§8Загрузить мир","§8Выгрузить мир").contains(title))return;e.setCancelled(true);if(!plugin.authed(p.getUniqueId())){p.closeInventory();return;}ItemStack i=e.getCurrentItem();if(i==null||!i.hasItemMeta()||i.getItemMeta().getDisplayName()==null)return;String name=ChatColor.stripColor(i.getItemMeta().getDisplayName());if(name==null)return;
  if(title.equals(TITLE)){if(name.equals("Создать мир")&&authorized(p)){p.closeInventory();awaitingWorldName.add(p.getUniqueId());p.sendMessage("§eВведи имя мира; для отмены напиши отмена.");return;}if(name.equals("Загрузить существующий")&&authorized(p)){openLoad(p);return;}if(name.equals("Выгрузить мир")&&authorized(p)){openUnload(p);return;}World w=Bukkit.getWorld(name);if(w!=null){p.closeInventory();p.teleport(w.getSpawnLocation());p.sendMessage("§aТелепорт в §e"+name);}return;}
  if(title.equals("§8Загрузить мир")){if(authorized(p)){World w=Bukkit.createWorld(new WorldCreator(name));p.closeInventory();p.sendMessage(w==null?"§cНе удалось загрузить мир.":"§aМир загружен: §e"+name);}return;}
  if(title.equals("§8Выгрузить мир")){World w=Bukkit.getWorld(name);if(authorized(p)&&w!=null&&!isProtected(w)&&w.getPlayers().isEmpty()){p.closeInventory();p.sendMessage(Bukkit.unloadWorld(w,true)?"§aМир выгружен.":"§cОшибка выгрузки.");}return;}
  if(title.equals(TYPE_TITLE)){String worldName=p.getPersistentDataContainer().get(new NamespacedKey(plugin,"world_create_name"),org.bukkit.persistence.PersistentDataType.STRING);if(worldName==null)return;String type=name.contains("Нижний")?"nether":name.equals("Энд")?"end":"normal";p.getPersistentDataContainer().remove(new NamespacedKey(plugin,"world_create_name"));p.closeInventory();create(p,worldName,type);}
 }
 @Override public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){if(args.length==1)return List.of("where","ui","list","tp","create","load","unload","delete","setjoin").stream().filter(x->x.startsWith(args[0].toLowerCase(Locale.ROOT))).toList();if(args.length==2&&(args[0].matches("(?i)tp|unload|delete|setjoin")))return Bukkit.getWorlds().stream().map(World::getName).filter(x->x.toLowerCase(Locale.ROOT).startsWith(args[1].toLowerCase(Locale.ROOT))).toList();if(args.length==3&&args[0].equalsIgnoreCase("create"))return List.of("normal","nether","end").stream().filter(x->x.startsWith(args[2].toLowerCase(Locale.ROOT))).toList();if(args.length==3&&args[0].equalsIgnoreCase("delete"))return List.of("DELETE");return Collections.emptyList();}
}
